import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String searchTerm = request.getParameter("q");
        String department = request.getParameter("dept");
        String sortCol = request.getParameter("sort");

        if (searchTerm == null || searchTerm.isEmpty()) {
            response.sendError(400, "Missing search parameter");
            return;
        }

        // Basic input length check
        if (searchTerm.length() > 100) {
            response.sendError(400, "Search term too long");
            return;
        }

        // Sanitize sort column against whitelist
        String[] allowedSorts = {"username", "email", "created_at", "department"};
        String safeSort = "username";
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equalsIgnoreCase(sortCol)) {
                    safeSort = allowed;
                    break;
                }
            }
        }

        // Build query - department filter uses parameterized approach
        // but search uses LIKE with concatenation for wildcard support
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT username, email, department, created_at FROM users WHERE ");
        sql.append("(username LIKE '%" + searchTerm + "%' OR email LIKE '%" + searchTerm + "%') ");

        if (department != null && !department.isEmpty()) {
            sql.append("AND department = ? ");
        }
        sql.append("ORDER BY " + safeSort + " ASC LIMIT 50");

        logger.info("Executing search query for term: " + searchTerm.substring(0, Math.min(10, searchTerm.length())) + "...");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            if (department != null && !department.isEmpty()) {
                stmt.setString(1, department);
            }

            ResultSet rs = stmt.executeQuery();
            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"username\": \"%s\", \"email\": \"%s\", \"department\": \"%s\", \"created_at\": \"%s\"}",
                    escapeJson(rs.getString("username")),
                    escapeJson(rs.getString("email")),
                    escapeJson(rs.getString("department")),
                    escapeJson(rs.getString("created_at")));
            }
            out.print("\n]");
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
